p.pol <- df |>
  ggplot( aes(x = YEAR,
           y = events_pol,
           group = COUNTRY)) +
  geom_line(colour = "grey", linewidth = 0.5) +
  theme(legend.position = "none") +
  labs(
    x = "Years",
    y = "Number of Political Violence Events",
    title = "Political Violence Trends",
    subtitle = "per country") +
  geom_line_interactive(
    colour = "#003B5D",
    linewidth = 0.5,
    hover_nearest = TRUE, 
    aes(tooltip = COUNTRY)
  ) +
  theme_classic()

p.pol <- girafe(ggobj = p.pol)
p.pol
