p.target <- df |> 
  ggplot( aes(x = YEAR,
           y = events_target,
           group = COUNTRY)) +
  geom_line(colour = "grey", linewidth = 0.5) +
  theme_bw() +
  theme(legend.position = "none") +
  labs(
    x = "Years",
    y = "Number of Events Targeting Civilians",
    title = "Civilian-targeted Events Trends",
    subtitle = "per country") +
  geom_line_interactive(
    colour = "#003B5D",
    linewidth = 0.5,
    hover_nearest = TRUE, 
    aes(tooltip = COUNTRY)
  ) +
  theme_classic()

p.target <- girafe(ggobj = p.target)
p.target
